import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.Lq8Lraw_.js";const k=JSON.parse('{"title":"13 merge vs rebase：黄金法则","description":"","frontmatter":{},"headers":[],"relativePath":"guide/collaboration/03-merge-vs-rebase.md","filePath":"guide/collaboration/03-merge-vs-rebase.md","lastUpdated":1792671989000}'),n={name:"guide/collaboration/03-merge-vs-rebase.md"};function l(p,s,d,h,r,o){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_13-merge-vs-rebase-黄金法则" tabindex="-1">13 merge vs rebase：黄金法则 <a class="header-anchor" href="#_13-merge-vs-rebase-黄金法则" aria-label="Permalink to &quot;13 merge vs rebase：黄金法则&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>学完本章，你将能够：</p><ul><li>用分支图解释 merge 与 rebase 对历史结构的根本差别</li><li>说明 rebase 为什么会改写提交哈希，以及由此带来的协作风险</li><li>熟练处理 rebase 过程中的冲突：<code>--continue</code> / <code>--skip</code> / <code>--abort</code></li><li>依据「分支是否已共享」做出 merge 还是 rebase 的决策</li><li>安全地强推个人分支：<code>--force-with-lease</code> 而不是 <code>--force</code></li></ul><h2 id="同一个目标-两种历史" tabindex="-1">同一个目标，两种历史 <a class="header-anchor" href="#同一个目标-两种历史" aria-label="Permalink to &quot;同一个目标，两种历史&quot;">​</a></h2><p>假设 <code>main</code> 和 <code>feature</code> 从同一点分叉，双方各有新提交：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        D---E feature</span></span>
<span class="line"><span>       /</span></span>
<span class="line"><span>  A---B---C main</span></span></code></pre></div><p>现在要把 <code>feature</code> 的改动集成到 <code>main</code>。两种方式的结果完全不同。</p><h3 id="merge-保留真实分叉" tabindex="-1">merge：保留真实分叉 <a class="header-anchor" href="#merge-保留真实分叉" aria-label="Permalink to &quot;merge：保留真实分叉&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        D---E feature</span></span>
<span class="line"><span>       /     \\</span></span>
<span class="line"><span>  A---B---C---M main</span></span></code></pre></div><p><code>M</code> 是一个<strong>合并提交</strong>，有两个父提交（<code>C</code> 和 <code>E</code>）。历史是真实的：它记录了「这两条线在某个时刻汇合」。代价是图会越来越复杂，<code>git log --graph</code> 在长期项目里会变成一团麻。</p><h3 id="rebase-把提交「搬」到新基底上" tabindex="-1">rebase：把提交「搬」到新基底上 <a class="header-anchor" href="#rebase-把提交「搬」到新基底上" aria-label="Permalink to &quot;rebase：把提交「搬」到新基底上&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  A---B---C main</span></span>
<span class="line"><span>           \\</span></span>
<span class="line"><span>            D&#39;---E&#39; feature</span></span></code></pre></div><p><code>D&#39;</code> 和 <code>E&#39;</code> 不是原来的 <code>D</code>、<code>E</code>，而是<strong>内容相同、父提交不同</strong>的新提交。哈希必然改变，因为提交哈希由「内容 + 父提交 + 作者 + 时间」共同决定，父提交变了，哈希就变了。</p><p>历史变成一条直线，读起来像「feature 是在最新 main 之后开发的」。但它<strong>不是真实发生过的时间线</strong>。</p><div class="tip custom-block"><p class="custom-block-title">一句话记住区别</p><p>merge 记录「发生了什么」，rebase 讲述「本来应该怎样」。</p></div><h2 id="黄金法则-不要-rebase-公共分支" tabindex="-1">黄金法则：不要 rebase 公共分支 <a class="header-anchor" href="#黄金法则-不要-rebase-公共分支" aria-label="Permalink to &quot;黄金法则：不要 rebase 公共分支&quot;">​</a></h2><blockquote><p><strong>已经被其他人拉取过的分支，不要 rebase。</strong></p></blockquote><p>原因不是风格偏好，而是数学结果：</p><ol><li>rebase 生成了新的提交 <code>D&#39;</code>、<code>E&#39;</code>，旧的 <code>D</code>、<code>E</code> 仍在同事本地。</li><li>同事下次 <code>pull</code> 时，Git 会看到两条历史：一条有 <code>D,E</code>，一条有 <code>D&#39;,E&#39;</code>，内容重复但哈希不同。</li><li>Git 只能做一次合并，结果是<strong>同一改动出现两次</strong>，或者产生大量冲突。</li><li>同事必须手动 <code>reset --hard origin/main</code> 才能修复，未推送的工作可能一起丢失。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同事本地：  A---B---C---D---E</span></span>
<span class="line"><span>远端（你强推后）：A---B---C---D&#39;---E&#39;</span></span></code></pre></div><p>这两条线再也无法自动对齐。</p><p>判断标准很简单：</p><table tabindex="0"><thead><tr><th>分支</th><th>是否可 rebase</th></tr></thead><tbody><tr><td>只有你在用、还没合并的 feature 分支</td><td>可以</td></tr><tr><td>已经 push 且同事基于它开发</td><td>不可以</td></tr><tr><td><code>main</code> / <code>develop</code> / <code>release</code> 等共享分支</td><td>绝对不可以</td></tr><tr><td>已合并进主干的提交</td><td>不需要，也不应该</td></tr></tbody></table><h2 id="决策表-什么时候用哪个" tabindex="-1">决策表：什么时候用哪个 <a class="header-anchor" href="#决策表-什么时候用哪个" aria-label="Permalink to &quot;决策表：什么时候用哪个&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th><th>理由</th></tr></thead><tbody><tr><td>个人 feature 分支落后 <code>main</code></td><td><code>rebase</code></td><td>保持线性历史，PR diff 干净</td></tr><tr><td>个人分支已经 push，只有自己在用</td><td><code>rebase</code> + <code>--force-with-lease</code></td><td>需要先确认远端没有被别人更新</td></tr><tr><td>多人共同开发的长周期分支</td><td><code>merge</code></td><td>改写历史会破坏所有人的本地仓库</td></tr><tr><td>把 feature 合入 <code>main</code></td><td><code>merge --no-ff</code> 或平台 Squash Merge</td><td>保留「这是一个完整功能」的边界</td></tr><tr><td>紧急修复要进多个分支</td><td><code>cherry-pick</code>（见第 15 章）</td><td>不需要整支合并</td></tr><tr><td>已经发布的错误提交</td><td><code>revert</code>（见第 16 章）</td><td>不改写历史</td></tr></tbody></table><h2 id="rebase-遇到冲突怎么办" tabindex="-1">rebase 遇到冲突怎么办 <a class="header-anchor" href="#rebase-遇到冲突怎么办" aria-label="Permalink to &quot;rebase 遇到冲突怎么办&quot;">​</a></h2><p>rebase 不是一次性操作，而是逐个提交重放。每个提交都可能冲突：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CONFLICT (content): Merge conflict in src/api/client.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># error: could not apply 8b1e0d4... feat: 新增重试逻辑</span></span></code></pre></div><p>流程与 merge 类似，但收尾命令不同：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 解决当前提交的冲突</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    编辑文件，删除冲突标记</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/api/client.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 继续重放下一个提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 如果这个提交的改动已经不需要了（例如已被上游实现），跳过它</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 放弃整个 rebase，回到开始前的状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --abort</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">rebase 冲突中的 ours / theirs 是反的</p><p>rebase 时 <code>ours</code> 是目标分支（<code>main</code>），<code>theirs</code> 是你正在重放的提交。别凭 merge 的直觉用 <code>--ours</code>。</p></div><p>另一个实用技巧：开启 <code>rerere</code> 后，同一冲突第二次出现时 Git 会自动套用你上次的解法（第 17 章）。</p><h2 id="用-pull-rebase-保持功能分支线性" tabindex="-1">用 <code>pull --rebase</code> 保持功能分支线性 <a class="header-anchor" href="#用-pull-rebase-保持功能分支线性" aria-label="Permalink to &quot;用 \`pull --rebase\` 保持功能分支线性&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 等价于 git fetch + git rebase origin/main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rebase</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 忘记加参数时，可以中止并用正确方式重来</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --abort</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设为个人默认（适合功能分支为主的团队）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull.rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><p>如果团队的主干要求线性历史（很多仓库开启了 &quot;Require linear history&quot;），<code>pull --rebase</code> 是日常必选项，否则你的合并提交会被分支保护规则拒绝。</p><h2 id="强推的正确姿势" tabindex="-1">强推的正确姿势 <a class="header-anchor" href="#强推的正确姿势" aria-label="Permalink to &quot;强推的正确姿势&quot;">​</a></h2><p>rebase 之后本地历史与远端分叉，普通 <code>push</code> 会被拒绝：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>! [rejected] feature/login -&gt; feature/login (non-fast-forward)</span></span></code></pre></div><p>此时只能强推，但要用带保护的条件强推：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-with-lease</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span></code></pre></div><p><code>--force-with-lease</code> 的语义是：<strong>只有当远端分支仍停留在我上次 fetch 时的位置，才允许覆盖</strong>。如果同事在此期间推了新提交，远端位置变了，推送会被拒绝。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 先 fetch，确认远端确实没有别人的新提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD..origin/feature/login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 应该为空</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 再强推</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-with-lease</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">永远不要对共享分支强推</p><p><code>git push --force origin main</code> 会无条件覆盖远端。即使你「确定」没人改过，也可能覆盖 CI 机器人的提交、别人的 hotfix，或者上一条被你遗忘的推送。团队里应把这条命令列入禁用清单。</p></div><h2 id="什么时候-rebase-反而更危险" tabindex="-1">什么时候 rebase 反而更危险 <a class="header-anchor" href="#什么时候-rebase-反而更危险" aria-label="Permalink to &quot;什么时候 rebase 反而更危险&quot;">​</a></h2><ul><li>分支上有<strong>合并提交</strong>：<code>rebase</code> 默认会丢弃合并提交，只保留一侧的改动，可能静默丢失代码。需要加 <code>--rebase-merges</code> 才能保留拓扑。</li><li>分支上有<strong>签名提交</strong>：rebase 后签名失效。</li><li>分支被<strong>CI 缓存或部署记录引用</strong>了具体哈希：改写后这些引用会指向不存在的对象。</li><li>你<strong>不确定是否有人基于该分支开发</strong>：默认按「有人」处理，先沟通。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ol><li><strong>rebase 后直接 <code>push --force</code></strong>：应使用 <code>--force-with-lease</code>，给自己留一道保险。</li><li><strong>在 <code>main</code> 上执行 <code>git pull --rebase</code> 后强推</strong>：公共分支被改写，全组遭殃。</li><li><strong>rebase 冲突时用 <code>--skip</code> 跳过所有冲突</strong>：可能把整个提交的改动都丢掉，必须逐个确认。</li><li><strong>以为 rebase 后提交哈希不变</strong>：哈希一定变，任何依赖哈希的脚本、链接、部署记录都会失效。</li><li><strong>rebase 前没提交/没 stash</strong>：Git 会拒绝执行，或者把未提交改动带入冲突现场。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>merge 保留分叉和合并提交，rebase 生成线性历史但会改写哈希。</li><li>黄金法则：已被他人拉取的公共分支禁止 rebase。</li><li>rebase 冲突用 <code>--continue</code> / <code>--skip</code> / <code>--abort</code> 收尾，ours/theirs 方向与 merge 相反。</li><li>rebase 后强推只能用 <code>--force-with-lease</code>，并对共享分支完全禁用强推。</li><li>选择依据不是「哪种历史更漂亮」，而是「这条分支有没有被别人依赖」。</li></ul>`,52)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
